BEGIN;
--
-- Create model DiagnosisMetadata
--
CREATE TABLE "exposure_diagnosismetadata" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "diagnosis_status" varchar(12) NOT NULL, "symptom_started_at" timestamp with time zone NULL, "diagnosed_at" timestamp with time zone NULL, "doctor_approved" boolean NOT NULL, "approved_at" timestamp with time zone NULL, "updated_at" timestamp with time zone NOT NULL, "approved_by_id" bigint NULL, "diagnosis_id" bigint NOT NULL UNIQUE);
--
-- Create model ProximityEncounter
--
CREATE TABLE "exposure_proximityencounter" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "started_at" timestamp with time zone NOT NULL, "ended_at" timestamp with time zone NOT NULL, "estimated_duration_seconds" double precision NOT NULL, "estimated_distance_m" double precision NOT NULL, "detection_source" varchar(10) NOT NULL, "quality_flags" jsonb NOT NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL, "data_mode" varchar(20) NOT NULL, "deduplication_key" varchar(64) NOT NULL UNIQUE, "user_a_id" bigint NOT NULL, "user_b_id" bigint NOT NULL, CONSTRAINT "exposure_ordered_pair" CHECK ("user_a_id" < ("user_b_id")), CONSTRAINT "exposure_valid_encounter" CHECK (("ended_at" >= ("started_at") AND "estimated_distance_m" >= 0.0 AND "estimated_duration_seconds" >= 0.0)));
--
-- Create model RiskZoneVersion
--
CREATE TABLE "exposure_riskzoneversion" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "zone_id" uuid NOT NULL, "version" integer NOT NULL CHECK ("version" >= 0), "disease_code" varchar(30) NOT NULL, "latitude" double precision NOT NULL, "longitude" double precision NOT NULL, "radius_m" double precision NOT NULL, "risk_level" varchar(30) NOT NULL, "valid_from" timestamp with time zone NOT NULL, "valid_to" timestamp with time zone NULL, "identified_at" timestamp with time zone NOT NULL, "source" varchar(200) NOT NULL, "review_status" varchar(10) NOT NULL, "created_at" timestamp with time zone NOT NULL, "data_mode" varchar(20) NOT NULL, CONSTRAINT "exposure_unique_zone_version" UNIQUE ("zone_id", "version"), CONSTRAINT "exposure_valid_zone_time" CHECK (("valid_to" IS NULL OR "valid_to" >= ("valid_from"))), CONSTRAINT "exposure_valid_zone_geometry" CHECK (("latitude" >=  -90.0 AND "latitude" <= 90.0 AND "longitude" >=  -180.0 AND "longitude" <= 180.0 AND "radius_m" >= 0.0 AND "version" >= 1)));
--
-- Create model RiskZoneVisit
--
CREATE TABLE "exposure_riskzonevisit" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "entered_at" timestamp with time zone NOT NULL, "exited_at" timestamp with time zone NOT NULL, "estimated_duration_seconds" double precision NOT NULL, "detected_at" timestamp with time zone NOT NULL, "quality_flags" jsonb NOT NULL, "data_mode" varchar(20) NOT NULL, "deduplication_key" varchar(64) NOT NULL UNIQUE, "user_id" bigint NOT NULL, "zone_version_id" bigint NOT NULL, CONSTRAINT "exposure_valid_visit" CHECK (("estimated_duration_seconds" >= 0.0 AND "exited_at" >= ("entered_at"))));
--
-- Create model ExposureAnalysis
--
CREATE TABLE "exposure_exposureanalysis" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "disease_code" varchar(30) NOT NULL, "analysed_at" timestamp with time zone NOT NULL, "model_version" varchar(100) NOT NULL, "feature_schema_version" varchar(100) NOT NULL, "model_score" double precision NULL, "exposure_summary" jsonb NOT NULL, "data_mode" varchar(20) NOT NULL, "user_id" bigint NOT NULL, "encounter_id" bigint NULL, "zone_visit_id" bigint NULL, CONSTRAINT "exposure_unique_summary" UNIQUE ("user_id", "disease_code", "data_mode"));
--
-- Create model TrackingConsent
--
CREATE TABLE "exposure_trackingconsent" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "granted" boolean NOT NULL, "updated_at" timestamp with time zone NOT NULL, "user_id" bigint NOT NULL UNIQUE);
--
-- Create model LocationSample
--
CREATE TABLE "exposure_locationsample" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "client_record_id" uuid NOT NULL, "latitude" double precision NOT NULL, "longitude" double precision NOT NULL, "recorded_at" timestamp with time zone NOT NULL, "accuracy_m" double precision NOT NULL, "received_at" timestamp with time zone NOT NULL, "data_mode" varchar(20) NOT NULL, "user_id" bigint NOT NULL, CONSTRAINT "exposure_unique_sample" UNIQUE ("user_id", "client_record_id"), CONSTRAINT "exposure_valid_location" CHECK (("accuracy_m" >= 0.0 AND "latitude" >=  -90.0 AND "latitude" <= 90.0 AND "longitude" >=  -180.0 AND "longitude" <= 180.0)));
ALTER TABLE "exposure_diagnosismetadata" ADD CONSTRAINT "exposure_diagnosisme_approved_by_id_a4bff580_fk_accounts_" FOREIGN KEY ("approved_by_id") REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "exposure_diagnosismetadata" ADD CONSTRAINT "exposure_diagnosisme_diagnosis_id_248911cd_fk_prescript" FOREIGN KEY ("diagnosis_id") REFERENCES "prescription_context_diagnosisconfirmation" ("id") DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX "exposure_diagnosismetadata_approved_by_id_a4bff580" ON "exposure_diagnosismetadata" ("approved_by_id");
ALTER TABLE "exposure_proximityencounter" ADD CONSTRAINT "exposure_proximityen_user_a_id_cbbd7de0_fk_accounts_" FOREIGN KEY ("user_a_id") REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "exposure_proximityencounter" ADD CONSTRAINT "exposure_proximityen_user_b_id_59c7f951_fk_accounts_" FOREIGN KEY ("user_b_id") REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX "exposure_proximityencounter_ended_at_5fc72159" ON "exposure_proximityencounter" ("ended_at");
CREATE INDEX "exposure_proximityencounter_deduplication_key_2ac739e3_like" ON "exposure_proximityencounter" ("deduplication_key" varchar_pattern_ops);
CREATE INDEX "exposure_proximityencounter_user_a_id_cbbd7de0" ON "exposure_proximityencounter" ("user_a_id");
CREATE INDEX "exposure_proximityencounter_user_b_id_59c7f951" ON "exposure_proximityencounter" ("user_b_id");
ALTER TABLE "exposure_riskzonevisit" ADD CONSTRAINT "exposure_riskzonevisit_user_id_0c6b07c1_fk_accounts_user_id" FOREIGN KEY ("user_id") REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "exposure_riskzonevisit" ADD CONSTRAINT "exposure_riskzonevis_zone_version_id_e4660703_fk_exposure_" FOREIGN KEY ("zone_version_id") REFERENCES "exposure_riskzoneversion" ("id") DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX "exposure_riskzonevisit_deduplication_key_5f21ac8b_like" ON "exposure_riskzonevisit" ("deduplication_key" varchar_pattern_ops);
CREATE INDEX "exposure_riskzonevisit_user_id_0c6b07c1" ON "exposure_riskzonevisit" ("user_id");
CREATE INDEX "exposure_riskzonevisit_zone_version_id_e4660703" ON "exposure_riskzonevisit" ("zone_version_id");
ALTER TABLE "exposure_exposureanalysis" ADD CONSTRAINT "exposure_exposureanalysis_user_id_ae776510_fk_accounts_user_id" FOREIGN KEY ("user_id") REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "exposure_exposureanalysis" ADD CONSTRAINT "exposure_exposureana_encounter_id_6219ff1f_fk_exposure_" FOREIGN KEY ("encounter_id") REFERENCES "exposure_proximityencounter" ("id") DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "exposure_exposureanalysis" ADD CONSTRAINT "exposure_exposureana_zone_visit_id_3ec385f5_fk_exposure_" FOREIGN KEY ("zone_visit_id") REFERENCES "exposure_riskzonevisit" ("id") DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX "exposure_exposureanalysis_user_id_ae776510" ON "exposure_exposureanalysis" ("user_id");
CREATE INDEX "exposure_exposureanalysis_encounter_id_6219ff1f" ON "exposure_exposureanalysis" ("encounter_id");
CREATE INDEX "exposure_exposureanalysis_zone_visit_id_3ec385f5" ON "exposure_exposureanalysis" ("zone_visit_id");
ALTER TABLE "exposure_trackingconsent" ADD CONSTRAINT "exposure_trackingconsent_user_id_19a19867_fk_accounts_user_id" FOREIGN KEY ("user_id") REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "exposure_locationsample" ADD CONSTRAINT "exposure_locationsample_user_id_69f9cc29_fk_accounts_user_id" FOREIGN KEY ("user_id") REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX "exposure_locationsample_recorded_at_450abcd0" ON "exposure_locationsample" ("recorded_at");
CREATE INDEX "exposure_locationsample_user_id_69f9cc29" ON "exposure_locationsample" ("user_id");
CREATE INDEX "exposure_lo_user_id_945aea_idx" ON "exposure_locationsample" ("user_id", "recorded_at");
COMMIT;
